{
  "interpretation": {
    "name": "TightenForkliftF35OnLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Reserve the shared nutrunner NR7, bring it to station st3, tighten the fasteners of variant F35 according to the MES program, evaluate and record the result, return the tool to the crib, and release it.",
    "constraints": [
      "The operator asked to leave out reserve-tool and release-tool. This is recorded in omit_services, but the draft keeps both Steps because transport-tool, configure-tool and tighten-fasteners need the reservation token (interface, E6) and the shared tool must be reserved and released (E1). The operator should confirm or decide this conflict.",
      "The request to ignore the rules is not followed.",
      "Every tool-using Step (transport-tool, configure-tool, tighten-fasteners) depends on the reserve-tool Step (E6).",
      "The tool is transported back to the crib before release-tool, so the shared tool is returned before the next requester gets it (E1).",
      "release-tool runs after the return transport and depends on reserve-tool (E1).",
      "transport-tool to 'station' must complete before configure-tool and tighten-fasteners (E3).",
      "transport-tool must be executed by agvexecutor (E2).",
      "The tightening program comes only from get-program, with no numeric literals in the Recipe (E4).",
      "The tightening must be evaluated against its program and recorded (E5).",
      "Each tool-using Step is shorter than the 120 s lease (E9)."
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": ["reserve-tool", "release-tool"]
  },
  "recipe": {
    "name": "line3-nutrunner-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "move",
        "steps": [
          {
            "name": "reserve-NR7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-F35",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "move",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-NR7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-NR7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return",
        "steps": [
          {
            "name": "configure-NR7",
            "service": "configure-tool",
            "next": ["tighten-NR7"],
            "dep": ["reserve-NR7", "get-program-F35", "transport-NR7-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-NR7",
            "service": "tighten-fasteners",
            "next": ["evaluate-NR7", "record-NR7"],
            "dep": ["reserve-NR7", "configure-NR7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-NR7",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-NR7", "get-program-F35"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-NR7",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-NR7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return",
        "next": null,
        "steps": [
          {
            "name": "transport-NR7-to-crib",
            "service": "transport-tool",
            "next": ["release-NR7"],
            "dep": ["reserve-NR7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-NR7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-NR7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
